solutionCode:
export async function esperarMilissegundos(ms) {
  if (typeof ms !== 'number' || ms < 0) {
    throw new Error('ms deve ser um número maior ou igual a zero');
  }
  await new Promise((resolve) => setTimeout(resolve, ms));
  return 'esperei ' + ms + 'ms';
}
